INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00006000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 6), 'unit6-lesson1', 'Will for Future, Promise, Offer, and Prediction', 'Will is used in future structures and for promises, offers, and predictions. The structure is Subject + will + V1.', '{"details":[{"concept":"Future Structure","explanation":"''Will'' is used to talk about things that will happen in the future.","example":"It will be Tuesday tomorrow.","burmese":"မနက်ဖန် အင်္ဂလိပ်နေ့ ဖြစ်မယ်။"},{"concept":"Promise","explanation":"''Will'' is used to make promises about the future.","example":"I will always love you.","burmese":"ငါနင်ကို အမြဲချစ်မယ်။"},{"concept":"Offer","explanation":"''Will'' is used to offer help.","example":"That phone is ringing; I will go and answer it.","burmese":"ဖုန်းလှမ်းနေတယ်။ ငါသွားကြည့်ပြီး ဖြေလိုက်မယ်။"},{"concept":"Prediction","explanation":"''Will'' is used to make predictions about the future.","example":"We will have two extra lessons this afternoon.","burmese":"ဒီနေ့လယ်ကျရင် ငါတို့ နောက်ထပ်သင်ခန်းစာ ၂ ခါ ရမယ်။"},{"concept":"Warning","explanation":"''Will'' can be used to give warnings.","example":"Don''t trust her, she will always tell you lies.","burmese":"သူမကို မယုံနဲ့။ သူမက မင်းကို အမြဲလိမ်နေတယ်။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00006001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 6), 'unit6-lesson2', 'Will in Type 1 Conditional Sentences', 'Will is used in Type 1 conditional sentences, which describe real or possible future conditions. The structure is: If + present simple, will + V1.', '{"details":[{"concept":"Type 1 Conditional","explanation":"Used for real or possible situations in the future. If the condition is met, the result will happen.","example":"We will go fishing at the weekend if the weather is good.","burmese":"ရာသီဥတု ကောင်းရင် ကျွန်တော်တို့ ငါးဖမ်းကြမယ်လေ။"},{"concept":"Type 1 Conditional (Education)","explanation":"Used for academic conditions as well.","example":"If you study well, you will pass the exam.","burmese":"မင်း စာလေ့လာရင် စာမေးပွဲ အောင်မှာပါ။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00006002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 6), 'unit6-lesson3', 'Would as Past Tense of Will', 'Would is the past tense form of will. It is used in reported speech and past narratives. The structure is Subject + would + V1.', '{"details":[{"concept":"Reported Speech","explanation":"When we report what someone said about the future in the past, we change ''will'' to ''would''.","example":"Jack said he would finish the work the next day.","burmese":"ဂျက်က သူ နောက်နေ့ ပြီးအောင်လုပ်မယ်လို့ ပြောခဲ့တယ်။"},{"concept":"Past Narrative","explanation":"Used in stories and past accounts of future intentions.","example":"Ann said she would write us soon.","burmese":"အန်က သူမ မကြာခင် ငါတို့ဆီ စာရေးမယ် ပြောခဲ့တယ်။"},{"concept":"Past Hope/Expectation","explanation":"Used to describe what someone expected or hoped would happen.","example":"He hoped she would come back.","burmese":"သူမပြန်လာမယ်လို့ သူ မျှော်လင့်ခဲ့တယ်။"}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00006003-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 6), 'unit6-lesson4', 'Would in Conditional Sentences', 'Would is used in Type 2 (unreal present) and Type 3 (unreal past) conditional sentences. These describe hypothetical or unreal situations.', '{"details":[{"concept":"Type 2 Conditional (Unreal Present)","explanation":"Used for hypothetical situations in the present that are unlikely or unreal. If + past simple, would + V1.","example":"I would phone Sue if I had her number.","burmese":"ငါမှာ သူ သူမဖုန်းနံပါတ်ရှိခဲ့ရင် ဆူကို ဆက်မှာမှာ ပါ။"},{"concept":"Type 3 Conditional (Unreal Past)","explanation":"Used for hypothetical situations in the past that did not happen. If + past perfect, would have + V3.","example":"If the weather had been good, we would have gone fishing on the weekend.","burmese":"ရာသီဥတု ကောင်းခဲ့ရင် ကျွန်တော်တို့ ဒီတစ်ပတ်ငါးဖမ်းကြမှာ ပါ။"}]}'::jsonb, 4) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00006004-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 6), 'unit6-lesson5', 'Would for Polite Requests', 'Would is more polite than will. It is used for polite requests and offers. The structure is Would + subject + V1?', '{"details":[{"concept":"Polite Request","explanation":"Used to make polite offers and requests.","example":"Would you like some juice?","burmese":"အခု ဖျော်ရည် သောက်ချင်လား။"},{"concept":"Polite Expression","explanation":"Used to express preferences politely.","example":"I would like to eat sandwich.","burmese":"ကျွန်မ ဆန်းဒ်ဝိုက် စားချင်တယ်။"}]}'::jsonb, 5) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00006000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 6), 'unit6-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":601,"question":"________ it snow yesterday?","options":["Will","Would","Shall"],"answer":"Would","explanation":"''Yesterday'' indicates past time, so we use ''Would'' (past tense of will). ''Will'' is for present/future. ''Shall'' is used with I/we for suggestions — neither matches past time. ''Yesterday'' ဆိုတာ အတိတ်ကာလဖြစ်တဲ့အတွက် ''Would'' ကိုသုံးပါ။","points":1},{"id":602,"question":"________ you like a coffee?","options":["Will","Would","Shall"],"answer":"Would","explanation":"''Would'' is used for polite requests and offers. ''Will'' is less polite. ''Shall'' is used with I/we for suggestions — it does not fit ''you''. ''Would'' ကို ယဉ်ကျေးတဲ့မေးခွန်းတွေမှာ သုံးပါ။","points":1},{"id":603,"question":"I ________ go to the cinema today.","options":["won''t","wouldn''t","shan''t"],"answer":"won''t","explanation":"''Today'' indicates present/future time, so we use ''won''t'' (will not). ''Wouldn''t'' is for past/hypothetical. ''Shan''t'' is formal British — ''won''t'' is the standard form. ''Today'' ဆိုတာ ဒီနေ့ဖြစ်တဲ့အတွက် ''won''t'' ကိုသုံးပါ။","points":1},{"id":604,"question":"He ________ probably arrive soon.","options":["will","would","shall"],"answer":"will","explanation":"''Soon'' indicates future time, so we use ''will''. ''Would'' is for past/hypothetical. ''Shall'' is used with I/we — not with ''he''. ''Soon'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် ''will'' ကိုသုံးပါ။","points":1},{"id":605,"question":"We ________ play if we had a ball.","options":["will","would","shall"],"answer":"would","explanation":"''If we had a ball'' is a Type 2 conditional (unreal). In Type 2, we use ''would + V1''. ''Will'' is for Type 1 (real) conditionals. ''Shall'' is for suggestions with I/we. ''If we had a ball'' က Type 2 conditional ဖြစ်တဲ့အတွက် ''would'' ကိုသုံးပါ။","points":1},{"id":606,"question":"Sam said he ________ come.","options":["won''t","wouldn''t","shan''t"],"answer":"wouldn''t","explanation":"''Sam said'' indicates reported speech. In reported speech, ''will'' changes to ''would'', so the negative is ''wouldn''t''. ''Won''t'' is for direct speech. ''Shan''t'' is formal. ''Sam said'' က reported speech ဖြစ်တဲ့အတွက် ''wouldn''t'' ကိုသုံးပါ။","points":1},{"id":607,"question":"They ________ paint it as you want.","options":["will","would","shall"],"answer":"will","explanation":"This is a straightforward statement about a future action. ''Will'' is used for future promises. ''Would'' is for past/hypothetical. ''Shall'' is for suggestions with I/we. ''Will'' ကို အနာဂတ်ကတိပြုချက်အဖြစ်သုံးပါ။","points":1},{"id":608,"question":"If I were you, I ________ go there.","options":["won''t","wouldn''t","shan''t"],"answer":"wouldn''t","explanation":"''If I were you'' is a Type 2 conditional (unreal). We use ''would + V1'' in the result clause. ''Won''t'' is for Type 1 conditionals. ''Shan''t'' is formal. ''If I were you'' က Type 2 conditional ဖြစ်တဲ့အတွက် ''wouldn''t'' ကိုသုံးပါ။","points":1},{"id":609,"question":"They ________ come tomorrow.","options":["will","would","shall"],"answer":"will","explanation":"''Tomorrow'' indicates future time, so we use ''will''. ''Would'' is for past/hypothetical. ''Shall'' is for suggestions with I/we. ''Tomorrow'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် ''will'' ကိုသုံးပါ။","points":1},{"id":610,"question":"I ________ be on time for the meeting.","options":["will","would","shall"],"answer":"will","explanation":"This is a statement about a future intention or promise. ''Will'' is used for future commitments. ''Would'' is for past/hypothetical. ''Shall'' can be used with I/we but ''will'' is more natural for promises. ''Will'' ကို အနာဂတ်ကတိပြုချက်အဖြစ်သုံးပါ။","points":1},{"id":611,"question":"He said he ________ read that book.","options":["won''t","wouldn''t","shan''t"],"answer":"wouldn''t","explanation":"''He said'' indicates reported speech. In reported speech, ''will'' changes to ''would'', so the negative is ''wouldn''t''. ''Won''t'' is for direct speech. ''Shan''t'' is formal. ''He said'' က reported speech ဖြစ်တဲ့အတွက် ''wouldn''t'' ကိုသုံးပါ။","points":1},{"id":612,"question":"________ you stop smoking this year?","options":["Will","Would","Shall"],"answer":"Will","explanation":"''This year'' indicates a future time frame. ''Will'' is used for future decisions. ''Would'' is for polite requests/hypothetical. ''Shall'' is used with I/we for suggestions. ''This year'' ဆိုတာ အနာဂတ်ကာလဖြစ်တဲ့အတွက် ''Will'' ကိုသုံးပါ။","points":1},{"id":613,"question":"Today ________ probably be a nice day for me.","options":["will","would","shall"],"answer":"will","explanation":"''Today'' indicates present/future time. ''Will'' is used for predictions about the future. ''Would'' is for past/hypothetical. ''Shall'' is for suggestions with I/we. ''Today'' ဆိုတာ ဒီနေ့ဖြစ်တဲ့အတွက် ''will'' ကိုသုံးပါ။","points":1},{"id":614,"question":"If Paula doesn''t go, I ________ go either.","options":["won''t","wouldn''t","shan''t"],"answer":"won''t","explanation":"''If Paula doesn''t go'' is a Type 1 conditional (real future). We use ''will + V1'' in the result clause. ''Wouldn''t'' is for Type 2 (unreal). ''Shan''t'' is formal. ''If Paula doesn''t go'' က Type 1 conditional ဖြစ်တဲ့အတွက် ''won''t'' ကိုသုံးပါ။","points":1},{"id":615,"question":"My mum said that she ________ be there by 8 o''clock.","options":["will","would","shall"],"answer":"would","explanation":"''My mum said'' indicates reported speech. In reported speech, ''will'' changes to ''would''. ''Will'' is for direct speech. ''Shall'' is for suggestions. ''My mum said'' က reported speech ဖြစ်တဲ့အတွက် ''would'' ကိုသုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

