INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00007000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 7), 'unit7-lesson1', 'Should for Advice and Expectations', '''Should'' is used to give advice, express expectations, or indicate what is right or wrong. The structure is Subject + should + V1.', '{"details":[{"concept":"Advice","explanation":"''Should'' is used to give advice about what is good or bad for someone.","example":"You shouldn''t drink alcohol.","burmese":"မင်း အရက်မသောက်သင့်ဘူး။"},{"concept":"Expectation","explanation":"''Should'' is used to say that you expect something to happen.","example":"There is a traffic jam on this road, you should go by Metro.","burmese":"ဒီလမ်းပေါ်မှာ ယာဉ်ကြောပိတ်ဆို့မှု ဖြစ်နေတယ်။ မင်း မီတရို စီးသင့်တယ်။"},{"concept":"Question Form","explanation":"''Should'' can be used to ask for advice or opinion.","example":"Should I go to the temple on Thursday?","burmese":"ကျွန်မ ကြာသပတေးနေ့ ဘုရားကျောင်း သွားသင့်လား။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00007001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 7), 'unit7-lesson2', 'Ought to for Obligation and Duty', '''Ought to'' is similar to ''should'' but expresses a slightly stronger obligation or moral duty. The structure is Subject + ought to + V1.', '{"details":[{"concept":"Moral Obligation","explanation":"''Ought to'' is used to express what is morally right or what someone should do.","example":"You ought to respect your elders.","burmese":"မင်း အသက်ကြီးသူတွေကို လေးစားသင့်တယ်။"},{"concept":"Prohibition (Negative)","explanation":"''Ought not to'' is used to say what someone should not do.","example":"You oughtn''t to ride a motorbike without a helmet.","burmese":"မင်း ဦးထုပ်မပါဘဲ ဆိုင်ကယ်မစီးသင့်ဘူး။"},{"concept":"Question Form","explanation":"''Ought'' can be used to ask for advice or confirmation.","example":"Ought she to call the police?","burmese":"သူမ ရဲကို ခေါ်သင့်လား။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00007002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 7), 'unit7-lesson3', 'Should vs Ought to', '''Should'' and ''ought to'' are very similar in meaning, but there are some differences in formality and strength.', '{"details":[{"concept":"Formality","explanation":"''Ought to'' is more formal than ''should''. ''Should'' is more common in everyday speech.","example":"You should study harder. (less formal) / You ought to study harder. (more formal)","burmese":"မင်း ပိုပြီး ကြိုးစားသင့်တယ်။ (ပုံမှန်) / မင်း ပိုပြီး ကြိုးစားသင့်ပါတယ်။ (တရားဝင်)"},{"concept":"Strength of Obligation","explanation":"''Ought to'' can express a slightly stronger moral obligation than ''should''.","example":"You should tell the truth. (advice) / You ought to tell the truth. (moral duty)","burmese":"မင်း အမှန်တရားကို ပြောသင့်တယ်။ (အကြံပြုချက်) / မင်း အမှန်တရားကို ပြောသင့်ပါတယ်။ (ကျင့်ဝတ်)"},{"concept":"Negative Form Difference","explanation":"''Should'' uses ''shouldn''t'' while ''ought to'' uses ''ought not to''.","example":"You shouldn''t be late. / You ought not to be late.","burmese":"မင်း နောက်ကျသင့်ဘူး။ / မင်း နောက်ကျသင့်ဘူး။"}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00007000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 7), 'unit7-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":701,"question":"They ________ have more parks in the city centre.","options":["should to","ought to","can to"],"answer":"ought to","explanation":"''Should to'' is grammatically incorrect — ''should'' is never followed by ''to''. ''Can to'' is also incorrect. ''Ought to'' is the correct form for expressing obligation. ''Should to'' က သဒ္ဒါမှားပါတယ်။ ''Ought to'' က မှန်ပါတယ်။","points":1},{"id":702,"question":"We ________ eat lots of fruit and vegetables every day.","options":["ought to","ought to be","should to"],"answer":"ought to","explanation":"''Ought to'' is followed by the base form (V1). ''Ought to be'' requires an adjective/noun after it. ''Should to'' is grammatically incorrect. ''Ought to'' ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":703,"question":"You ________ do that!","options":["shouldn''t","don''t should","can''t should"],"answer":"shouldn''t","explanation":"''Don''t should'' and ''can''t should'' are grammatically incorrect. Modal verbs use ''shouldn''t'' for negatives. ''Don''t should'' နဲ့ ''can''t should'' က သဒ္ဒါမှားပါတယ်။ ''Shouldn''t'' က မှန်ပါတယ်။","points":1},{"id":704,"question":"We ________ invite Cassie and Jack to dinner.","options":["ought","ought to","should to"],"answer":"ought to","explanation":"''Ought'' must be followed by ''to'' before the verb. ''Should to'' is incorrect — ''should'' is never followed by ''to''. ''Ought'' ပြီးနောက်မှာ ''to'' ထည့်ပါ။","points":1},{"id":705,"question":"We ________ leave soon.","options":["should","should to","ought"],"answer":"should","explanation":"''Should to'' is incorrect — ''should'' is followed directly by the base verb. ''Ought'' requires ''to'' after it. ''Should leave'' is correct. ''Should to'' က သဒ္ဒါမှားပါတယ်။","points":1},{"id":706,"question":"________ we call the police?","options":["Should","Ought","Could"],"answer":"Should","explanation":"''Should'' can be used directly in questions without ''to''. ''Ought'' requires ''to'' (Ought we to...?). ''Could'' is for ability/permission — not for advice. ''Should'' က ''to'' မပါဘဲ မေးခွန်းမှာသုံးနိုင်ပါတယ်။","points":1},{"id":707,"question":"________ we to tell Jane the news?","options":["Should","Ought","Must"],"answer":"Ought","explanation":"''Ought'' requires ''to'' in questions (Ought we to...?). ''Should'' does not use ''to''. ''Must'' does not use ''to'' in questions. Since ''to'' is present, ''Ought'' is correct. ''Ought'' က မေးခွန်းမှာ ''to'' ပါဖို့လိုပါတယ်။","points":1},{"id":708,"question":"It ________ a very good conference.","options":["should","should be","ought"],"answer":"should","explanation":"''Should'' expresses expectation about the conference. ''Should be'' would need an adjective/noun complement. ''Ought'' requires ''to''. ''Should'' က expectation ကိုဖော်ပြပါတယ်။","points":1},{"id":709,"question":"You ________ enjoy the holiday.","options":["should","should be","ought"],"answer":"should","explanation":"''Should'' is followed by the base form (V1). ''Enjoy'' is V1, so ''should enjoy'' is correct. ''Should be'' requires an adjective/noun. ''Ought'' requires ''to''. ''Should'' ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":710,"question":"You ________ tell the truth.","options":["ought to","should be","ought"],"answer":"ought to","explanation":"''Ought to'' is followed by V1. ''Tell'' is V1, so ''ought to tell'' is correct. ''Should be'' requires an adjective/noun. ''Ought'' alone is incomplete — it needs ''to''. ''Ought to'' ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":711,"question":"She ________ find a better job.","options":["should","should be","ought"],"answer":"should","explanation":"''Should'' is followed by V1. ''Find'' is V1, so ''should find'' is correct. ''Should be'' requires an adjective/noun. ''Ought'' requires ''to''. ''Should'' ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":712,"question":"You ________ switch off the light whenever you leave a room.","options":["ought to","ought to be","should to"],"answer":"ought to","explanation":"''Ought to'' is followed by V1. ''Switch'' is V1, so ''ought to switch'' is correct. ''Ought to be'' requires an adjective/noun. ''Should to'' is grammatically incorrect. ''Ought to'' ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":713,"question":"I told him that he ________ careful.","options":["should","should be","ought"],"answer":"should","explanation":"''Should'' is used for advice in reported speech. ''He should careful'' means ''he should be careful'' with ''be'' implied. ''Should be'' is also valid but ''should'' is the more natural choice. ''Should'' က အကြံပြုချက်အဖြစ်သုံးပါ။","points":1},{"id":714,"question":"You ________ listen to classical music if you want to relax.","options":["ought to","ought to be","should to"],"answer":"ought to","explanation":"''Ought to'' is followed by V1. ''Listen'' is V1, so ''ought to listen'' is correct. ''Ought to be'' requires an adjective/noun. ''Should to'' is incorrect. ''Ought to'' ပြီးနောက်မှာ V1 ကိုသုံးပါ။","points":1},{"id":715,"question":"If you want to lose weight, you ________ cut out snacks and junk food.","options":["ought to","oughtn''t to","should to"],"answer":"ought to","explanation":"This is advice about what to do to lose weight, so the affirmative ''ought to'' is correct. ''Oughtn''t to'' would mean you should NOT cut out snacks. ''Should to'' is grammatically incorrect. ''Ought to'' က အကြံပြုချက်ဖြစ်တဲ့အတွက် မှန်ပါတယ်။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

-- --------------------------------------------------------------------------
-- Unit 8: Can / Could
-- --------------------------------------------------------------------------

INSERT INTO units (id, unit_number, title, lesson_count, exercise_count, question_count)
VALUES ('00000008-0000-4000-8000-000000000001', 8, 'Can / Could', 3, 1, 15)
ON CONFLICT (unit_number) DO UPDATE SET
  id = EXCLUDED.id,
  title = EXCLUDED.title,
  lesson_count = EXCLUDED.lesson_count,
  exercise_count = EXCLUDED.exercise_count,
  question_count = EXCLUDED.question_count;

INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00008000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 8), 'unit8-lesson1', 'Can for Present/Future Ability and Permission', 'Can is used to talk about the ability to do something at a given time in the present or future. It is used to make statements about what is possible. Can is more informal. The structure is Subject + can + V1.', '{"details":[{"concept":"Present Ability","explanation":"''Can'' is used to talk about current abilities and skills.","example":"He can speak Chinese fluently.","burmese":"သူ အင်္ဂလိပ်စာကို ကောင်းကောင်းကျွမ်းကျင်စွာ ပြောနိုင်တယ်။"},{"concept":"Future Ability","explanation":"''Can'' can also refer to future possibilities.","example":"You can take a holiday tomorrow if you want.","burmese":"မင်းနားချင်ရင် မနက်ဖန်နားနိုင်တယ်။"},{"concept":"Negative (Inability)","explanation":"''Cannot'' (can''t) is used to express inability or impossibility.","example":"I cannot drink too much.","burmese":"ငါအရမ်းများများ မသောက်နိုင်ဘူး။"},{"concept":"Informal Request","explanation":"''Can'' is used for informal requests and asking permission.","example":"Can you take me to the Victoria station?","burmese":"မင်း ငါ့ကို ဗစ်တိုးရီးယား ရထားဘူတာဆီ ခေါ်သွားပေးနိုင်မလား။"},{"concept":"Asking Permission","explanation":"''Can'' is used to ask for permission informally.","example":"Can I borrow your car tomorrow?","burmese":"မင်းရဲ့ကားကို မနက်ဖန် ငါ ငှားရမ်းနိုင်မလား။"}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00008001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 8), 'unit8-lesson2', 'Could for Past Ability and Polite Requests', 'Could is used to talk about past time ability. Could is also used as a polite way of telling or asking to do something. Could is more formal and polite than can. The structure is Subject + could + V1.', '{"details":[{"concept":"Past Ability","explanation":"''Could'' is used to talk about abilities in the past.","example":"I could run 10 miles when I was young.","burmese":"ငါငယ်ငယ်က ၁၀ မိုင် ပြေးနိုင်ခဲ့တယ်။"},{"concept":"Past Inability","explanation":"''Could not'' (couldn''t) is used to express inability in the past.","example":"I could not take chilli when I was 12.","burmese":"ကျွန်မ ၁၂ နှစ်တုန်းက ငရုတ်သီး မစားနိုင်ခဲ့ဘူး။"},{"concept":"Polite Request","explanation":"''Could'' is used for polite requests. It is more formal than ''can''.","example":"Could you lock the door when you leave?","burmese":"မင်းထွက်သွားရင် တံခါးခတ်ပေးနိုင်မလား။"},{"concept":"Polite Permission","explanation":"''Could'' is used to ask for permission in a more formal way.","example":"Could I choose my own doctor?","burmese":"ကျွန်တော်တို့အတွက်ဆရာဝန်ကို ကျွန်တော်တို့ဘက်က ကိုယ်တိုင် လွတ်လပ်စွာ ရွေးချယ်နိုင်မလား။"}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00008002-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 8), 'unit8-lesson3', 'Can vs Could', 'Can and could are both modal verbs used for ability and permission, but they differ in formality and time reference.', '{"details":[{"concept":"Formality","explanation":"''Could'' is more formal and polite than ''can''. Use ''could'' in formal situations.","example":"Can you help me? (informal) / Could you help me? (formal/polite)","burmese":"ငါ့ကို ကူညီပေးနိုင်မလား။ (ပုံမှန်) / ငါ့ကို ကူညီပေးနိုင်မလားခင်ဗျ။ (တရားဝင်/ယဉ်ကျေး)"},{"concept":"Time Reference","explanation":"''Can'' is for present/future, while ''could'' is for past or hypothetical situations.","example":"I can swim now. (present) / I could swim when I was 5. (past)","burmese":"ငါ အခု ရေကူးနိုင်တယ်။ (လက်ရှိ) / ငါ ၅ နှစ်တုန်းက ရေကူးနိုင်ခဲ့တယ်။ (အတိတ်)"},{"concept":"Request Strength","explanation":"''Could'' is softer and more polite than ''can'' for requests.","example":"Can I sit here? (casual) / Could I sit here? (very polite)","burmese":"ဒီမှာ ထိုင်လို့ ရလား။ (ပုံမှန်) / ဒီမှာ ထိုင်လို့ ရမလားခင်ဗျ။ (အလွန်ယဉ်ကျေး)"}]}'::jsonb, 3) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00008000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 8), 'unit8-ex1', 'multiple_choice', 'Choose the correct alternative to complete each sentence.', '[{"id":801,"question":"He ________ speak Chinese fluently.","options":["can","could","may"],"answer":"can","explanation":"''Can'' is used for present ability. He currently has the ability to speak Chinese. ''Could'' is for past ability. ''May'' is for permission/possibility — not for ability. ''Can'' ကို လက်ရှိအရည်အချင်းအတွက်သုံးပါ။","points":1},{"id":802,"question":"I ________ run 10 miles when I was young.","options":["can","could","may"],"answer":"could","explanation":"''Could'' is used for past ability. ''When I was young'' indicates past time. ''Can'' is for present ability. ''May'' is for permission/possibility. ''Could'' ကို အတိတ်အရည်အချင်းအတွက်သုံးပါ။","points":1},{"id":803,"question":"You ________ take a holiday tomorrow if you want.","options":["can","could","may"],"answer":"can","explanation":"''Can'' is used for future possibilities and informal permissions. ''Could'' is more formal/polite. ''May'' is for formal permission. This is a straightforward statement, so ''can'' is natural. ''Can'' ကို အနာဂတ်ဖြစ်နိုင်ခြေအတွက် ပုံမှန်သုံးပါ။","points":1},{"id":804,"question":"________ you lock the door when you leave?","options":["Can","Could","May"],"answer":"Could","explanation":"''Could'' is used for polite requests. It is more formal and polite than ''can''. ''May'' is for formal permission. ''Could'' ကို ယဉ်ကျေးတဲ့မေးခွန်းတွေမှာသုံးပါ။","points":1},{"id":805,"question":"I ________ drink too much.","options":["can''t","couldn''t","may not"],"answer":"can''t","explanation":"''Can''t'' is used for present inability. ''Couldn''t'' is for past inability. ''May not'' is for prohibition — not inability. This sentence describes a current state. ''Can''t'' ကို လက်ရှိမတတ်နိုင်မှုအတွက်သုံးပါ။","points":1},{"id":806,"question":"I ________ not take chilli when I was 12.","options":["can","could","may"],"answer":"could","explanation":"''Could not'' is used for past inability. ''When I was 12'' indicates past time. ''Cannot'' is for present inability. ''May'' is for permission/possibility. ''Could'' ကို အတိတ်မတတ်နိုင်မှုအတွက်သုံးပါ။","points":1},{"id":807,"question":"________ I choose my own doctor?","options":["Can","Could","May"],"answer":"Could","explanation":"''Could'' is used for polite permission requests. ''Can'' is more informal. ''May'' is also formal but ''Could'' is more natural for this context. ''Could'' ကို ယဉ်ကျေးတဲ့ခွင့်ပြုချက်မေးခွန်းအတွက်သုံးပါ။","points":1},{"id":808,"question":"She ________ swim when she was five.","options":["can","could","may"],"answer":"could","explanation":"''Could'' is used for past ability. ''When she was five'' indicates past time. ''Can'' is for present ability. ''May'' is for permission/possibility. ''Could'' ကို အတိတ်အရည်အချင်းအတွက်သုံးပါ။","points":1},{"id":809,"question":"You ________ borrow my pen if you need it.","options":["can","could","may"],"answer":"can","explanation":"''Can'' is used for informal permission. This is a casual offer. ''Could'' would be more formal. ''May'' is very formal. ''Can'' ကို ပုံမှန်ခွင့်ပြုချက်အတွက်သုံးပါ။","points":1},{"id":810,"question":"I ________ not attend the meeting yesterday.","options":["can","could","may"],"answer":"could","explanation":"''Could not'' is used for past inability. ''Yesterday'' indicates past time. ''Cannot'' is for present inability. ''May'' is for permission/possibility. ''Could'' ကို အတိတ်မတတ်နိုင်မှုအတွက်သုံးပါ။","points":1},{"id":811,"question":"________ you help me with this bag, please?","options":["Can","Could","May"],"answer":"Could","explanation":"''Could'' is used for polite requests with ''please''. ''Can'' is more informal. ''May'' is for formal permission — not for asking for help. ''Could'' ကို ''please'' ပါတဲ့ ယဉ်ကျေးတဲ့မေးခွန်းတွေမှာသုံးပါ။","points":1},{"id":812,"question":"He ________ play the guitar very well.","options":["can","could","may"],"answer":"can","explanation":"''Can'' is used for present ability. He currently has the ability to play guitar well. ''Could'' is for past ability. ''May'' is for permission/possibility. ''Can'' ကို လက်ရှိအရည်အချင်းအတွက်သုံးပါ။","points":1},{"id":813,"question":"When I was a child, I ________ stay up late.","options":["can","could","may"],"answer":"could","explanation":"''Could'' is used for past ability. ''When I was a child'' indicates past time. ''Can'' is for present ability. ''May'' is for permission/possibility. ''Could'' ကို အတိတ်အရည်အချင်းအတွက်သုံးပါ။","points":1},{"id":814,"question":"You ________ not smoke in this building.","options":["can","could","may"],"answer":"can","explanation":"''Can not'' (cannot) is used for present prohibition. This is a current rule. ''Could not'' would be for past prohibition. ''May'' can also express prohibition but ''can'' is more common for rules. ''Can'' ကို လက်ရှိပိတ်ပင်ချက်အတွက်သုံးပါ။","points":1},{"id":815,"question":"________ I use your phone? I left mine at home.","options":["Can","Could","May"],"answer":"Can","explanation":"''Can'' is used for informal permission requests. This is a casual request between people who know each other. ''Could'' would be more formal. ''May'' is very formal. ''Can'' ကို ပုံမှန်ခွင့်ပြုချက်မေးခွန်းအတွက်သုံးပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

